#!/usr/bin/env bash
# GENERATED by /slava:util:scriptify from .claude/commands/slava/util/claude-sync-download.md
# Covers the deterministic tail (original steps 3 + 4). Steps 1-2 (browser export
# click, Gmail MCP poll) stay INLINE in the twin — they need the model's tool context.
#
# Contract:  $1 = download_url  (produced by the inline Gmail step; the URL extracted
#            from the "your data is ready" email body, shape https://claude.ai/export/<uuid>/download/<hash>)
# DRY_RUN=1  skips `open`, the Desktop wait, and `claude-sync` — validates args + control flow only.
set -euo pipefail

DESKTOP="$HOME/Desktop"
DOWNLOADS="$HOME/Downloads"
WAIT_SECS="${WAIT_SECS:-30}"   # how long to wait for the browser download to land

# --- arg validation: fail loud, never default (scriptify data-flow contract) ---
URL="${1:-}"
if [ -z "$URL" ]; then
  echo "ERROR: missing arg \$1 (download_url). Usage: $0 <https://claude.ai/export/.../download/...>" >&2
  exit 1
fi
case "$URL" in
  https://claude.ai/export/*/download/*) : ;;
  *) echo "ERROR: \$1 does not look like a claude.ai export download URL: $URL" >&2; exit 1 ;;
esac

MARKER="$(mktemp)"   # timestamp marker to find zips created after we trigger the download

if [ "${DRY_RUN:-}" = "1" ]; then
  echo "[DRY_RUN] would: open \"$URL\""
  echo "[DRY_RUN] would: wait up to ${WAIT_SECS}s for data-*.zip newer than marker in $DESKTOP or $DOWNLOADS"
  echo "[DRY_RUN] would: copy newest zip to $DOWNLOADS/"
  echo "[DRY_RUN] would: run claude-sync"
  rm -f "$MARKER"
  echo "[DRY_RUN] args valid; control flow OK"
  exit 0
fi

# --- step 3: trigger native browser download (uses logged-in Chrome session; Cloudflare-gated) ---
echo "Opening download URL in browser..."
open "$URL"

# wait for the zip to appear on Desktop OR Downloads (newer than MARKER) —
# the browser may save directly to either depending on its download-location setting
echo "Waiting up to ${WAIT_SECS}s for the zip..."
ZIP=""
for _ in $(seq 1 "$WAIT_SECS"); do
  sleep 1
  ZIP="$(find "$DESKTOP" "$DOWNLOADS" -maxdepth 1 -name 'data-*.zip' -newer "$MARKER" 2>/dev/null | sort | tail -1 || true)"
  [ -n "$ZIP" ] && break
done
rm -f "$MARKER"

if [ -z "$ZIP" ]; then
  echo "ERROR: no new data-*.zip appeared on $DESKTOP or $DOWNLOADS within ${WAIT_SECS}s (download may have failed / returned HTML)." >&2
  exit 2
fi
echo "Downloaded: $ZIP"

# copy to ~/Downloads where claude-sync scans (no-op if it already landed there)
DEST="$DOWNLOADS/$(basename "$ZIP")"
if [ "$ZIP" != "$DEST" ]; then
  cp "$ZIP" "$DEST"
  echo "Copied to: $DEST"
else
  echo "Already in $DOWNLOADS"
fi

# --- step 4: run the importer ---
# claude-sync is a zsh alias (~/.zshrc), invisible to this non-interactive shell — call its target directly.
echo "Running claude-sync..."
~/projects/private/claude-conversations/sync
